<?php declare(strict_types=1);$base=config('app.base_path');?><div class="page-header"><div><h1>Tourism Reviews</h1><p>Moderate visitor feedback before it becomes public.</p></div></div><div class="card table-responsive"><table class="table"><thead><tr><th>User</th><th>Target</th><th>Rating</th><th>Review</th><th>Status</th><th>Moderate</th></tr></thead><tbody><?php foreach($reviews as $r):?><tr><td><?=htmlspecialchars((string)($r['user_name']??'Visitor'))?></td><td><?=htmlspecialchars($r['reviewable_type'].' #'.$r['reviewable_id'])?></td><td><?=str_repeat('★',(int)$r['rating'])?></td><td><?=htmlspecialchars((string)($r['review']??''))?></td><td><?=htmlspecialchars($r['status'])?></td><td><form method="post" action="<?=$base?>/tourism/reviews/<?=$r['id']?>/status"><select name="status"><option>Pending</option><option>Approved</option><option>Rejected</option><option>Hidden</option></select><button class="btn btn-secondary">Update</button></form></td></tr><?php endforeach;if(!$reviews):?><tr><td colspan="6">No reviews yet.</td></tr><?php endif;?></tbody></table></div>
